'use strict';
(function(){
  function ctrl(w){return typeof safiWorkStatusControl==='function'?safiWorkStatusControl(w):(['Completed','Closed','Cancelled'].includes(w.status)?'CLOSED':'ACTIVE')}
  function icon(kind){const x={core:'<path d="M14.7 6.3a4 4 0 0 1-5.2 5.2L4 17l3 3 5.5-5.5a4 4 0 0 1 5.2-5.2l-3 3-3-3 3-3Z"/>',asset:'<path d="m4 7 8-4 8 4-8 4-8-4Z"/><path d="M4 7v10l8 4 8-4V7M12 11v10"/>',work:'<path d="M14.7 6.3a4 4 0 0 1-5.2 5.2L5 16l-2 5 5-2 7.5-7.5a4 4 0 0 1 5.2-5.2l-3 3-3-3 3-3Z"/>',pm:'<circle cx="12" cy="12" r="8"/><path d="M12 8v4l3 2"/>',stock:'<path d="m4 7 8-4 8 4-8 4-8-4Z"/><path d="M4 7v10l8 4 8-4V7M12 11v10"/>',team:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/>'};return '<svg viewBox="0 0 24 24">'+(x[kind]||x.core)+'</svg>'}
  function bg(){const w=document.querySelector('.workspace');if(!w||w.querySelector('.v60-live-bg'))return;const e=document.createElement('div');e.className='v60-live-bg';e.innerHTML='<span class="v60-link l1"></span><span class="v60-link l2"></span><span class="v60-link l3"></span><span class="v60-link l4"></span><span class="v60-node n1"></span><span class="v60-node n2"></span><span class="v60-node n3"></span><span class="v60-node n4"></span><span class="v60-node n5"></span><span class="v60-node n6"></span>';w.insertBefore(e,w.firstChild)}
  function dashboard(){
    const user=currentUser(),site=safiActiveSite?.()||state.sites[0],assets=state.assets.filter(a=>a.type!=='Site'&&(!site||safiSiteAllowed(a))),work=state.workOrders.filter(w=>!site||safiSiteAllowed(w)),active=work.filter(w=>ctrl(w)==='ACTIVE'),offline=assets.filter(a=>a.operatingState==='Offline'),online=assets.length-offline.length,over=active.filter(w=>w.due&&w.due<day(0)),critical=active.filter(w=>['Critical','Emergency','Highest'].includes(w.priority)),low=state.parts.filter(p=>partOnHand(p)<Number(p.min||0)),people=state.users.filter(u=>u.active).length;
    const due=state.scheduledMaintenance.filter(pm=>!pm.paused&&pm.status!=='Paused'&&pm.status!=='Archived').filter(pm=>{const d=pm.triggers?.find(t=>t.type==='Time')?.nextDue||pm.nextDue;return /^\d{4}-\d{2}-\d{2}$/.test(String(d||''))&&d<=day(7)});
    const upcoming=active.filter(w=>w.due).sort((a,b)=>String(a.due).localeCompare(String(b.due))).slice(0,6),risks=[...over.map(w=>({t:w.id+' · '+w.title,d:(getAsset(w.assetIds?.[0])?.name||'No asset')+' · overdue',r:'work-orders',l:'bad'})),...offline.map(a=>({t:a.code+' · '+a.name+' offline',d:a.downtimeReason||'Asset unavailable',r:'downtime',l:'bad'})),...low.map(p=>({t:p.code+' · '+p.name+' below minimum',d:partOnHand(p)+' '+p.uom+' on hand · min '+p.min,r:'planning',l:'warn'}))].slice(0,6);
    const ready=[['Asset availability',assets.length?Math.round(online/assets.length*100):100],['Assigned work',active.length?Math.round(active.filter(w=>(w.assigneeIds||[]).length||w.assigneeGroupId).length/active.length*100):100],['Stock readiness',state.parts.length?Math.round(state.parts.filter(p=>partOnHand(p)>=Number(p.min||0)).length/state.parts.length*100):100]];
    return '<div class="v60-dashboard"><section class="v60-hero"><div><div class="v60-eyebrow"><i></i>Maintenance command center</div><h1>Welcome, '+esc(user?.name?.split(' ')[0]||'there')+'.</h1><p>See the condition of the maintenance system in one place. Assets, work, preventive maintenance, stock and people remain connected without forcing you through dozens of screens.</p><div class="v60-actions"><button class="button primary" data-action="add-asset">＋ Add asset</button><button class="button" data-action="new-work">Create work order</button><button class="button" data-action="add-part">Add stock item</button></div></div><aside class="v60-network"><div class="v60-network-head"><span><strong>Live maintenance network</strong><small>'+online+' of '+assets.length+' assets online</small></span><b class="v60-live"><i></i>Monitoring</b></div><div class="v60-map"><span class="v60-wire a"></span><span class="v60-wire w"></span><span class="v60-wire s"></span><span class="v60-wire t"></span><div class="v60-card a"><strong><b></b>Assets</strong><small>'+assets.length+' tracked</small></div><div class="v60-card w"><strong><b></b>Work</strong><small>'+active.length+' open</small></div><div class="v60-card s"><strong><b></b>Stock</strong><small>'+low.length+' alerts</small></div><div class="v60-card t"><strong><b></b>Team</strong><small>'+people+' active</small></div><div class="v60-core">'+icon('core')+'</div></div></aside></section>'+
    '<section class="v60-kpis">'+
    '<button class="v60-kpi assets" data-route="assets"><span class="ico">'+icon('asset')+'</span><small>Assets</small><strong>'+assets.length+'</strong><p>'+offline.length+' offline · '+online+' online</p><span class="vis"></span></button>'+
    '<button class="v60-kpi work" data-route="work-orders"><span class="ico">'+icon('work')+'</span><small>Open work</small><strong>'+active.length+'</strong><p>'+over.length+' overdue · '+critical.length+' critical</p><span class="vis"></span></button>'+
    '<button class="v60-kpi pm" data-route="pm"><span class="ico">'+icon('pm')+'</span><small>PM due soon</small><strong>'+due.length+'</strong><p>Time / meter driven maintenance</p><span class="vis"></span></button>'+
    '<button class="v60-kpi stock" data-route="planning"><span class="ico">'+icon('stock')+'</span><small>Stock alerts</small><strong>'+low.length+'</strong><p>'+state.parts.length+' stock items tracked</p><span class="vis"></span></button>'+
    '<button class="v60-kpi team" data-route="people"><span class="ico">'+icon('team')+'</span><small>Team</small><strong>'+people+'</strong><p>Active maintenance users</p><span class="vis"></span></button></section>'+
    '<section class="v60-grid"><article class="v60-panel"><div class="v60-panel-head"><span><h2>Operational attention</h2><p>Real exceptions that need action now</p></span><button class="button small" data-route="maintenance-outlook">Outlook</button></div>'+(risks.length?risks.map(x=>'<button class="v60-row" data-route="'+x.r+'"><span><strong>'+esc(x.t)+'</strong><small>'+esc(x.d)+'</small></span><span class="v50-pill '+x.l+'">Review</span></button>').join(''):'<div class="v60-empty"><strong>No urgent exceptions</strong><span>Current tracked operations are within configured thresholds.</span></div>')+'</article><article class="v60-panel"><div class="v60-panel-head"><span><h2>Upcoming work</h2><p>Nearest planned completion dates</p></span><button class="button small" data-route="calendar">Planner</button></div>'+(upcoming.length?upcoming.map(w=>'<button class="v60-row" data-open-work="'+esc(w.id)+'"><span><strong>'+esc(w.id)+' · '+esc(w.title)+'</strong><small>'+esc(getAsset(w.assetIds?.[0])?.name||'No asset')+' · '+esc(w.status)+'</small></span><span>'+dateFmt(w.due)+'</span></button>').join(''):'<div class="v60-empty"><strong>No scheduled work</strong><span>Create a work order or preventive plan.</span></div>')+'</article></section>'+
    '<section class="v60-panel"><div class="v60-panel-head"><span><h2>System readiness</h2><p>Signals that make planning reliable</p></span><button class="button small" data-route="reports">Reports</button></div><div class="v60-ready">'+ready.map(x=>'<div class="v60-ready-row"><b>'+x[0]+'</b><span><i style="width:'+x[1]+'%"></i></span><em>'+x[1]+'%</em></div>').join('')+'</div></section></div>'
  }
  bg();renderDashboard=dashboard;window.renderDashboard=dashboard;
  const base=render;render=function(){base();bg()};window.render=render;if(ui.route==='dashboard')render()
})();